using WAID.Domain.Repairs;namespace WAID.Application.Services;public enum RepairCandidateStatus{Eligible,BlockedByPolicy,Conflict,PrerequisiteMissing}public sealed record RepairRankingFactors(int Evidence,int Benefit,int RiskPenalty,int ReversibilityBonus,int DowntimePenalty,int ContextAdjustment,int ConflictPenalty,int PrerequisitePenalty,int PolicyPenalty,int FeedbackAdjustment,int FinalScore);public sealed record RepairRankingContext(IReadOnlySet<string> BlockedRepairIds,IReadOnlyDictionary<string,IReadOnlyList<string>> Conflicts,IReadOnlySet<string> AvailablePrerequisites,IReadOnlyDictionary<string,RepairFeedbackAggregate> Feedback,int MaximumDowntimeMinutes=60,SafetyLevel MaximumRisk=SafetyLevel.High){public static RepairRankingContext Default{get;}=new(new HashSet<string>(StringComparer.OrdinalIgnoreCase),new Dictionary<string,IReadOnlyList<string>>(StringComparer.OrdinalIgnoreCase),new HashSet<string>(["administrator","restore-point","backup"],StringComparer.OrdinalIgnoreCase),new Dictionary<string,RepairFeedbackAggregate>(StringComparer.OrdinalIgnoreCase));}public sealed record RepairFeedbackAggregate(string RepairId,int Successes,int Failures,int Rollbacks){public int Samples=>Math.Min(1000,Math.Max(0,Successes)+Math.Max(0,Failures)+Math.Max(0,Rollbacks));public int Adjustment=>Samples<3?0:Math.Clamp((int)Math.Round((double)(Successes-Failures-Rollbacks)/Samples*10),-10,10);}public sealed record RepairRecommendationDecision(string RepairId,RepairCandidateStatus Status,string Reason,RepairRankingFactors Factors,bool AutoSelectable,IReadOnlyList<string> Conflicts,IReadOnlyList<string> MissingPrerequisites);public sealed record RepairRankingRun(Guid Id,DateTimeOffset GeneratedAtUtc,string RankingVersion,IReadOnlyList<PrioritizedRepair> Ranked,IReadOnlyList<RepairRecommendationDecision> Decisions,IReadOnlyDictionary<string,RepairFeedbackAggregate> Feedback);public interface IRepairRecommendationRepository{Task SaveAsync(RepairRankingRun run,CancellationToken token);Task<RepairRankingRun?> GetLatestAsync(CancellationToken token);}